use super::*;
#[derive(Clone,Copy)]
struct OriginalPagedIdentitySource<'a>{pages:&'a[&'a[u8]],page_bytes:usize,identity:OriginalWireSourceIdentity}
impl RetainedWireByteSource for OriginalPagedIdentitySource<'_>{
 fn original_source_identity(&self)->OriginalWireSourceIdentity{self.identity}
 fn byte_at(&self,index:usize)->Option<u8>{if index>=self.identity.extent{return None}self.pages.get(index/self.page_bytes)?.get(index%self.page_bytes).copied()}
}

fn observe<T>(operation:impl FnOnce()->T)->(T,usize,usize){semio_framework_trace_memory_testing::observe_backing(operation)}
fn receipt(owner:&mut RetainedHistoryIdDecode,grant:RetainedCloneGrant,born:usize,released:usize)->usize{let(received,progress)=owner.take_receipt().unwrap();assert_eq!(received,grant);assert!(progress.fits(grant));assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));progress.copied_bytes}
fn decode_hex(text:&str)->Vec<u8>{text.as_bytes().chunks_exact(2).map(|pair|u8::from_str_radix(std::str::from_utf8(pair).unwrap(),16).unwrap()).collect()}
fn close_text(mut text:Option<String>,grant:RetainedCloneGrant)->usize{let(result,born,released)=observe(||RetainedWireFieldDecode::admit_received_text(&mut text,grant).unwrap());assert_eq!((born,released),(0,0));let mut owner=result.unwrap();assert_eq!(owner.take_receipt().unwrap().1.copied_bytes,0);let(_,born,released)=observe(||owner.close_step(grant).unwrap());let(received,progress)=owner.take_receipt().unwrap();assert_eq!(received,grant);assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));assert!(owner.terminal_is_empty());released}
fn close_identity<S:RetainedWireByteSource+?Sized>(owner:&mut RetainedHistoryIdDecode,source:&S,prior:&dyn OriginalHistoryEdits,grant:RetainedCloneGrant)->usize{owner.cancel();let mut released_sum=0;for _ in 0..64{if owner.terminal_is_empty(){return released_sum}let demand=owner.demands(source,prior,grant.maximum_copy_bytes).unwrap();for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:demand.depth-1,..grant}]{let(step,born,released)=observe(||owner.close_step(source,prior,denied).unwrap());assert_eq!(step,RetainedHistoryIdDecodeStep::Blocked);assert_eq!((born,released),(0,0));assert!(owner.receipt().is_none());}if demand.release_bytes>0{let(step,born,released)=observe(||owner.close_step(source,prior,RetainedCloneGrant{maximum_release_bytes:demand.release_bytes-1,..grant}).unwrap());assert_eq!(step,RetainedHistoryIdDecodeStep::Blocked);assert_eq!((born,released),(0,0));}let(_,born,released)=observe(||owner.close_step(source,prior,grant).unwrap());assert_eq!(receipt(owner,grant,born,released),0);released_sum+=released;}panic!("original identity close did not terminate")}
#[test]
fn original_history_identity_native_ranges_and_prior_edit_keep_exact_receipts(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let p=&law["grant"];let n=|key:&str|p[key].as_u64().unwrap()as usize;let grant=RetainedCloneGrant{maximum_items:n("items"),maximum_copy_bytes:n("copyBytes"),maximum_capacity_bytes:n("capacityBytes"),maximum_release_bytes:n("releaseBytes"),maximum_depth:n("depth")};
 let prior=[HistoryEdit{id:law["priorEditIds"][0].as_str().unwrap().to_owned(),actor:None,started_at:String::new(),finished_at:None,verb:None,line:None,ops:Vec::new(),inverse:Vec::new(),meta:None,lane:None}];let prior_identity=(prior[0].id.as_ptr(),prior[0].id.len(),prior[0].id.capacity());
 for value in law["fields"].as_array().unwrap(){for paged in[false,true]{let mut original=decode_hex(law["dictionaryWireHex"].as_str().unwrap());let dictionary_end=original.len();original.extend_from_slice(&decode_hex(value["hex"].as_str().unwrap()));let field_end=original.len();original.extend_from_slice(&decode_hex(law["source"]["suffixHex"].as_str().unwrap()));let page_bytes=if paged{law["source"]["pageBytes"].as_u64().unwrap()as usize}else{original.len()};let pages=original.chunks(page_bytes).collect::<Vec<_>>();let identity=OriginalWireSourceIdentity{address:original.as_ptr()as usize,extent:original.len(),authority:if paged{Some((law["source"]["operation"].as_u64().unwrap(),law["source"]["generation"].as_u64().unwrap()))}else{None}};let source=OriginalPagedIdentitySource{pages:&pages,page_bytes,identity};let mut dictionary=RetainedSourceDictionary::new(&source);dictionary.begin_record(&source,0,dictionary_end,grant).unwrap();dictionary.take_receipt().unwrap();let(mut dictionary_born,mut dictionary_released)=(0,0);
  for _ in 0..64{if dictionary.is_ready(){break}let(_,born,released)=observe(||dictionary.advance(&source,grant).unwrap());let(received,progress)=dictionary.take_receipt().unwrap();assert_eq!(received,grant);assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));assert_eq!(progress.copied_bytes,0);dictionary_born+=born;dictionary_released+=released;}assert!(dictionary.is_ready());
  for cancellation in[0,1,3,64]{for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:1,..grant}]{let(owner,born,released)=observe(||RetainedHistoryIdDecode::admit(&source,(dictionary_end,field_end),&dictionary,&prior,denied).unwrap());assert!(owner.is_none());assert_eq!((born,released),(0,0));}
   let(result,born,released)=observe(||RetainedHistoryIdDecode::admit(&source,(dictionary_end,field_end),&dictionary,&prior,grant).unwrap());assert_eq!((born,released),(0,0));let mut owner=result.unwrap();assert_eq!(owner.consumed_end(),field_end);assert_eq!(owner.source_identity(),identity);assert_eq!(receipt(&mut owner,grant,born,released),0);for changed_identity in[OriginalWireSourceIdentity{address:identity.address+1,..identity},OriginalWireSourceIdentity{extent:identity.extent-1,..identity},OriginalWireSourceIdentity{authority:Some((43,8)),..identity}]{let changed=OriginalPagedIdentitySource{identity:changed_identity,..source};let(result,born,released)=observe(||owner.step(&changed,&prior,grant));assert!(result.is_err());assert_eq!((born,released),(0,0));assert!(owner.receipt().is_none());assert!(owner.demands(&changed,&prior,grant.maximum_copy_bytes).is_err())}let(mut birth,mut release,mut copied)=(0,0,0);
   for _ in 0..cancellation{if owner.is_ready(){break}let demand=owner.demands(&source,&prior,grant.maximum_copy_bytes).unwrap();for(axis,denied)in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:demand.depth-1,..grant},RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes.saturating_sub(1),..grant},RetainedCloneGrant{maximum_copy_bytes:0,..grant}].into_iter().enumerate(){if(axis==2&&demand.capacity_bytes==0)||(axis==3&&demand.copy_bytes==0){continue}let(step,born,released)=observe(||owner.step(&source,&prior,denied).unwrap());assert_eq!(step,RetainedHistoryIdDecodeStep::Blocked);assert_eq!((born,released),(0,0));assert!(owner.receipt().is_none());}let(_,born,released)=observe(||owner.step(&source,&prior,grant).unwrap());birth+=born;release+=released;copied+=receipt(&mut owner,grant,born,released);assert_eq!((prior[0].id.as_ptr(),prior[0].id.len(),prior[0].id.capacity()),prior_identity);}
   if cancellation==64{assert!(owner.is_ready());let mut recipient=None;let(_,born,released)=observe(||owner.take_ready_into(&source,&prior,&mut recipient,grant).unwrap());assert_eq!((born,released),(0,0));assert_eq!(receipt(&mut owner,grant,born,released),0);assert_eq!(recipient.as_deref(),value["expected"].as_str());assert_eq!(copied,recipient.as_ref().unwrap().len());let(_,born,released)=observe(||owner.step(&source,&prior,grant).unwrap());assert_eq!((born,released),(0,0));assert_eq!(receipt(&mut owner,grant,born,released),0);release+=close_text(recipient,grant);}else{release+=close_identity(&mut owner,&source,&prior,grant)}assert!(owner.terminal_is_empty());assert_eq!(birth,release);let(_,born,released)=observe(||drop(owner));assert_eq!((born,released),(0,0));
  }
  dictionary.cancel();for _ in 0..64{if dictionary.terminal_is_empty(){break}let(_,born,released)=observe(||dictionary.close_step(&source,grant).unwrap());let(received,progress)=dictionary.take_receipt().unwrap();assert_eq!(received,grant);assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));assert_eq!(progress.copied_bytes,0);dictionary_released+=released;}assert!(dictionary.terminal_is_empty());assert_eq!(dictionary_born,dictionary_released);
 }}
 let[mut prior]=prior;let original_id=Some(std::mem::take(&mut prior.id));assert_eq!(close_text(original_id,grant),prior_identity.2);
}
